description:
Design an Infinite Impulse Response (IIR) filter that takes a 16-bit input sample and processes it using a feedback equation: 
output = (b0 * input + b1 * input_delay1 + b2 * input_delay2 - a1 * output_delay1 - a2 * output_delay2) >> 15;
Where b0, b1, b2, a1, and a2 are filter coefficients. The filter should maintain the previous output and input samples for feedback in its internal state.

code:
module iir_filter #(parameter B0 = 16'h1, B1 = 16'h1, B2 = 16'h1, A1 = 16'h1, A2 = 16'h1) (  
    input clk,  
    input rst,  
    input [15:0] input_sample,  
    output reg [15:0] output_sample  
);  
    reg [15:0] input_delay1;  
    reg [15:0] input_delay2;  
    reg [15:0] output_delay1;  
    reg [15:0] output_delay2;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            output_sample <= 16'b0;  
            input_delay1 <= 16'b0;  
            input_delay2 <= 16'b0;  
            output_delay1 <= 16'b0;  
            output_delay2 <= 16'b0;  
        end else begin  
            output_sample <= (B0 * input_sample + B1 * input_delay1 + B2 * input_delay2 - A1 * output_delay1 - A2 * output_delay2) >> 15;  
            input_delay2 <= input_delay1;  
            input_delay1 <= input_sample;  
            output_delay2 <= output_delay1;  
            output_delay1 <= output_sample;  
        end  
    end  
endmodule

