module echo_cancellation_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg echo;
    reg received_signal;
    reg rst;
    wire canceled_signal;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    echo_cancellation dut (
        .clk(clk),
        .echo(echo),
        .received_signal(received_signal),
        .rst(rst),
        .canceled_signal(canceled_signal)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            rst = 1;
            received_signal = 0;
            echo = 0;
            @(posedge clk);
            #2 rst = 0;
            @(posedge clk);
        end
        endtask
